                  cbn [cells_size csize Nat.add Nat.mul Z.of_nat Pos.of_succ_nat Pos.succ Pos.add Pos.mul length repeat List.map];
                  intros ? Hz; apply Z.
  Ltac trj H Z Hz := eapply (junk_transport_ag (outside W) m0 m2 AG); [exact H|]; intros ? Hz; apply Z.
