  Lemma Z_rec_sh : forall x lo' k y, In x (chunk_list st) -> x <> ch ->
    ch_lo x <= lo' -> lo' + 8 * k <= ch_end x -> lo' mod 8 = 0 -> 0 <= k -> sh lo' <= y < sh lo' + k -> outside W y.
Proof.
